if(mq)fillOptions('measurement',mq.id,'basic_utm');
else [['basic_utm','Temel UTM / platform sinyali'],['platform_pixel','Platform pikseli'],['pixel_capi_crm','Piksel + CRM'],['none','Henüz hazır değil']].forEach(([v,t])=>{const o=el('option',t);o.value=v;$('measurement').append(o);});
$('brief').value='';
$('audience-description').value='';
$('identity').value='';
const demoOption=el('option','Dinamik deneyim · hazırlanmış örnek değerler');demoOption.value='interactive';$('fixture').prepend(demoOption);$('fixture').value='interactive';
const readinessBox=el('div'),readinessLabel=el('label','Demo senaryoda hesap hazırlığı');readinessLabel.htmlFor='demo-readiness';const readiness=el('select');readiness.id='demo-readiness';[['core','Standart kanallar hazır varsayılsın'],['all','Partnerler dahil hazır varsayılsın'],['none','Hiçbir hesap hazır değil']].forEach(([v,t])=>{const o=el('option',t);o.value=v;readiness.append(o);});readinessBox.append(readinessLabel,readiness,el('p','Yalnız simülasyon varsayımıdır; hiçbir hesap bağlı veya doğrulanmış değildir.','hint'));$('fixture').after(readinessBox);
const dateParts=Object.fromEntries(new Intl.DateTimeFormat('en-GB',{timeZone:'Europe/Istanbul',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(new Date()).map(p=>[p.type,p.value]));$('start').value=`${dateParts.year}-${dateParts.month}-${dateParts.day}`;
function go(step) {if(step>state.unlocked || (step>=2 && (state.stale || state.contentBinding!==productionPlan().signature)))return;state.step=step;document.body.classList.toggle('planning-stage',step===1);document.querySelectorAll('.step').forEach((n,i)=>n.hidden=i!==step);document.querySelectorAll('#step-nav button').forEach((n,i)=>{n.disabled=i>state.unlocked;n.classList.toggle('active',i===step);n.classList.toggle('done',i<step);if(i===step)n.setAttribute('aria-current','step');else n.removeAttribute('aria-current');});if(step===3)review();$('main').focus();window.scrollTo(0,0);}
document.querySelectorAll('[data-step]').forEach(b=>b.addEventListener('click',()=>go(+b.dataset.step)));
// Incomplete branch-rule rows are not executable: use each question's showWhen instead.
function structuredDetail(q){
  const schema=q.type==='date_range'?[['start','Başlangıç','date'],['end','Bitiş','date']]:q.type==='currency_pair'?[['regular','Önceki fiyat (TL)','number'],['offer','Kampanyalı fiyat (TL)','number']]:q.type==='fundraising_finance'?[['kind','Bağış şekli',[['money','Para bağışı'],['materials','Ürün / malzeme desteği'],['volunteer','Gönüllü emek'],['mixed','Birden fazla destek türü']]],['channel','Destek nasıl iletilecek?',[['official_account','Kuruluşun resmî hesabı / IBAN'],['official_site','Kuruluşun web sitesi'],['authorized_platform','Yetkili bağış platformu'],['in_person','Yerinde / doğrudan destek']]],['target','Hedef tutar (TL) · varsa','number'],['url','Bağış sayfası bağlantısı','url']]:null;
  if(!schema)return null;const root=el('div',undefined,'structured-detail'),saved=state.answers[q.id];root.id=`q-${q.id}`;const controls={};for(const [key,text,type] of schema){const box=el('div'),label=el('label',text),input=el(Array.isArray(type)?'select':'input');input.id=`q-${q.id}-${key}`;label.htmlFor=input.id;if(Array.isArray(type)){const empty=el('option','Şimdi belirtmeyeceğim');empty.value='';input.append(empty);for(const [value,text] of type){const o=el('option',text);o.value=value;input.append(o);}}else{input.type=type;if(type==='number'){input.min='0';input.max='1000000000000';input.step='0.01';}}input.value=saved&&typeof saved==='object'?saved[key]||'':'';controls[key]=input;box.append(label,input);root.append(box);}
  const constraints=()=>{if(controls.end){controls.end.min=controls.start.value;controls.end.setCustomValidity(controls.start.value&&controls.end.value&&controls.end.value<controls.start.value?'Bitiş tarihi başlangıçtan önce olamaz.':'');}if(q.type==='fundraising_finance'){const nonCash=['materials','volunteer'].includes(controls.kind.value);for(const option of controls.channel.options)option.disabled=nonCash&&!!option.value&&option.value!=='in_person';if(controls.channel.selectedOptions[0]?.disabled)controls.channel.value='';controls.target.disabled=nonCash;controls.target.parentElement.hidden=nonCash;if(nonCash)controls.target.value='';const needsUrl=!destinationApplies()&&['official_site','authorized_platform'].includes(controls.channel.value);controls.url.disabled=!needsUrl;controls.url.required=needsUrl;controls.url.maxLength=2048;controls.url.placeholder='https://ornek.example/bagis';controls.url.parentElement.hidden=!needsUrl;if(!needsUrl)controls.url.value='';controls.url.setCustomValidity(needsUrl?(B.validateDestination('own_website',{url:controls.url.value.trim()}).url||''):'');}};
  const project=()=>{const values=Object.fromEntries(Object.entries(controls).filter(([,n])=>n.value&&!n.disabled).map(([key,n])=>[key,n.value]));if(Object.keys(values).length)state.answers[q.id]=values;else delete state.answers[q.id];};const update=()=>{constraints();project();briefChanged();};constraints();if(saved&&typeof saved==='object')project();for(const input of Object.values(controls))input.addEventListener('input',update);return root;
}
function branches() {
  const root=$('branch-fields');root.replaceChildren();
  const primary=briefBase();state.answers=B.pruneContextAnswers(state.answers,D.questions,primary);const base={...state.answers,...primary};for(const key of Object.keys(state.branchCustom))if(state.answers[key]!=='other')delete state.branchCustom[key];
  const qs=D.questions.filter(q=>q.stage===1 && q.id!=='S1_B02' && B.branchApplies(q,base.S1_Q01,base.S1_Q04) && Object.keys(q.showWhen).length && Object.entries(q.showWhen).every(([key,values])=>Array.isArray(base[key])?values.some(v=>base[key].includes(v)):values.includes(base[key])));
  if(!qs.length)return;
  const primaryIds=base.S1_Q01==='sale_promotion'?['S1_B01','S1_B03','S1_P01','S1_P03']:base.S1_Q01==='fundraising'?['S1_F01','S1_F02','S1_F04']:[];
  const detail=el('details',undefined,'optional-details');detail.open=base.S1_Q01==='public_issue';detail.append(el('summary',primaryIds.length?'Ek ayrıntılar · istersen şimdi tamamla':`Bu isteğe özel ${qs.length} kısa ayrıntı`));
  const fields=el('div',undefined,'details-inner field-pair'),primaryFields=el('div',undefined,'primary-context-fields field-pair');
  qs.forEach(q=>{const box=el('div'),id=`q-${q.id}`;const l=el('label',q.label);l.htmlFor=id;box.append(l);
    const structured=structuredDetail(q);if(structured){box.className='structured-question';l.removeAttribute('for');if(q.type==='fundraising_finance')l.textContent='Nasıl bir destek topluyorsun?';box.append(structured,el('p',q.type==='fundraising_finance'?'Bu aşamada hesap numarası istemiyoruz. Ödeme kanalı daha sonra doğrulanır.':q.help,'hint'));(primaryIds.includes(q.id)?primaryFields:fields).append(box);return;}
    const statusOptions=['S1_F02','S1_F05','S1_REP02'].includes(q.id)?[{value:'declared_ready',label:'Hazır olduğunu beyan ediyorum · doğrulama bekliyor'},{value:'preparing',label:'Hazırlanıyor'},{value:'not_available',label:'Mevcut değil'}]:[];
    const options=statusOptions.length?statusOptions:D.options.filter(o=>o.questionId===q.id);let input;
    if(options.length){input=el('select');const blank=el('option','Şimdi belirtmeyeceğim');blank.value='';input.append(blank);options.forEach(o=>{const n=el('option',o.label);n.value=o.value;input.append(n);});}
    else {input=el(q.type==='textarea'?'textarea':'input');if(q.type==='number'){input.type='number';input.min='0';}else if(input.tagName==='INPUT')input.type='text';input.maxLength=q.validation.max_chars||600;input.placeholder=['single_select','textarea','number'].includes(q.type)?'Kısa bilgi ekle':'Taslak notu · belge / onay doğrulanmaz';}
    input.id=id;input.value=state.answers[q.id]||'';input.dataset.question=q.id;input.addEventListener('input',()=>{state.answers[q.id]=input.value;invalidate();});box.append(input,el('p',q.help,'hint'));
    if(input.tagName==='SELECT'&&options.some(o=>o.value==='other')){const customBox=el('div',undefined,'brief-custom'),customLabel=el('label','Diğer seçimini açıkla'),customInput=el('input');customInput.id=`${id}-other`;customInput.className='branch-other-text';customInput.dataset.customQuestion=q.id;customInput.maxLength=200;customInput.value=state.branchCustom[q.id]||'';customLabel.htmlFor=customInput.id;customBox.append(customLabel,customInput);box.append(customBox);const update=()=>{const active=input.value==='other';customBox.hidden=!active;customInput.disabled=!active;customInput.required=active;if(!active){customInput.value='';customInput.setCustomValidity('');delete state.branchCustom[q.id];}refreshManualBrief();};input.addEventListener('change',update);customInput.addEventListener('input',()=>{customInput.setCustomValidity('');state.branchCustom[q.id]=customInput.value;});customBox.hidden=input.value!=='other';customInput.required=input.value==='other';customInput.disabled=input.value!=='other';}
    (primaryIds.includes(q.id)?primaryFields:fields).append(box);
  });if(primaryFields.children.length)root.append(primaryFields);detail.append(fields,el('p','Eklediğin bilgiler çalışma taslağında tutulur. Belge ve izin doğrulaması ayrıca yapılır.','hint details-hint'));if(fields.children.length)root.append(detail);
}
branches();
function syncLocks(){document.querySelectorAll('#step-nav button').forEach((n,i)=>n.disabled=i>state.unlocked);}
function invalidate(){state.stale=true;state.adaptations=null;$('adapt-content').disabled=true;$('content-next').disabled=true;$('platform-previews').replaceChildren();$('production-status').textContent='Plan değişti. Üretim ihtiyaçlarını yeniden doğrula.';state.contentBinding=null;state.unlocked=Math.min(state.unlocked,1);syncLocks();if(state.plan)$('decision-status').textContent='Koşullar değişti. Önce dağılımı yeniden öner; önceki sonuç güncel değil.';}
function briefChanged(){invalidate();state.briefDirty=true;state.unlocked=0;syncLocks();}
$('brief-form').addEventListener('input',briefChanged);$('brief-form').addEventListener('change',briefChanged);
function briefBase(){return {S1_Q01:$('communication').value,S3_Q02:$('business').value,S3_Q03:$('sector').value,S1_Q04:$('action').value};}
function briefObject(){const answers={...state.answers};document.querySelectorAll('[data-question]').forEach(n=>{const canonical=n.dataset.question!=='S1_B02'||D.options.some(o=>o.questionId==='S1_B02'&&o.value===n.value);if(n.value&&canonical)answers[n.dataset.question]=n.value;else delete answers[n.dataset.question];});const visible=B.pruneContextAnswers(answers,D.questions,briefBase());return {mode:mode(),communication:$('communication').value,business:$('business').value,action:$('action').value,description:$('brief').value.trim(),audience:$('audience-description').value.trim(),sector:$('sector').value,risk:$('risk').value,identity:$('identity').value.trim(),message:$('message').value.trim(),branch:visible,custom:briefCustom(),destination:readDestination(),brief_policy:B.version};}
function contentChanged(){state.adaptations=null;state.unlocked=Math.min(state.unlocked,2);$('platform-previews').replaceChildren();$('production-status').textContent='Fikir değişti. Kanala özel taslakları yeniden hazırla.';syncLocks();}
function makeCards(){const previous=state.cards;if(previous.length)state.history.push({cards:structuredClone(previous),selected:state.selected,brief:structuredClone(state.brief)});state.batch++;state.cards=S.cards(state.brief,state.batch).map((c,i)=>c.title===previous[i]?.title?S.cards(state.brief,state.batch+1)[i]:c);state.selected=null;contentChanged();renderCards();}
$('brief-form').addEventListener('submit',e=>{e.preventDefault();if($('brief').value.trim()&&$('brief').value.trim().length<10){$('brief').setCustomValidity('Kısa not yazacaksan en az 10 karakter gir.');$('brief').reportValidity();return;}
  if(!validateBrief()){return;}const b=briefObject(),changed=JSON.stringify(b)!==JSON.stringify(state.brief);if(changed){state.cards=[];state.selected=null;state.history=[];}state.brief=b;state.briefDirty=false;
  if(!state.goalManual)$('goal').value=({visit_store:'store_visits',visit_website:'traffic',buy_online:'ecommerce_purchase',buy_marketplace:'ecommerce_purchase',message_whatsapp:'calls_messages',call:'calls_messages',fill_form:'lead_generation',book_appointment:'appointment',register_event:'event_registration',download_app:'app_install',apply_job:'job_application',donate:'donation',join_membership:'lead_generation',follow_engage:'engagement',understand:'awareness',remember:'awareness'})[b.action]||'awareness';
  state.unlocked=1;configureJourney();$('intent-summary').textContent=`${label('business')} · ${label('action')} · ${state.brief.audience}`;go(1);if(mode()!=='organic')recommend();else {state.plan=null;state.stale=false;renderRequirements($('plan-production'));}
});$('brief').addEventListener('input',()=>$('brief').setCustomValidity(''));
function artwork(card){const art=el('div',undefined,`art art-${['a','b','c'][card.kind]} theme-${card.theme||'product'}`);const illustration=el('div',undefined,'demo-illustration');illustration.innerHTML=S.illustration(card.theme);art.append(illustration);const copy=el('div',undefined,'art-copy');copy.style.left=`${card.x}%`;copy.style.top=`${card.y}%`;copy.style.width=`${90-card.x}%`;copy.append(el('div',card.title,'art-title'),el('p',card.message,'art-message'));art.append(copy,el('span',card.cta,'art-cta'),el('span',state.brief?.identity||'YAPARO · ÖRNEK ÇİZİM','art-brand'));return art;}
function renderCards(){const root=$('concepts');root.replaceChildren();state.cards.forEach(c=>{const article=el('article',undefined,`concept-card ${state.selected===c.id?'selected':''}`);article.append(artwork(c));const info=el('div',undefined,'concept-info');info.append(el('h2',c.angle),el('p',c.message),el('div',`${c.tone} · Ortak yaratıcı fikir`,'concept-meta'),el('small',`Kanca: ${c.hook} · CTA: ${c.cta}`));
    const actions=el('div',undefined,'card-actions'),choose=btn(state.selected===c.id?'✓ Seçildi':'Bu yönü seç',()=>{state.selected=c.id;contentChanged();renderCards();},'choose');choose.setAttribute('aria-pressed',String(state.selected===c.id));
    actions.append(choose,btn('Düzenle',()=>openEditor(c)),btn('Benzerini gör',()=>{c.edits.push({title:c.title,message:c.message,cta:c.cta,x:c.x,y:c.y,theme:c.theme});Object.assign(c,S.alternative(c,state.brief));c.revision++;contentChanged();renderCards();}));
    if(c.edits.length)actions.append(btn('Geri al',()=>{Object.assign(c,c.edits.pop());c.revision++;contentChanged();renderCards();}));info.append(actions);article.append(info);root.append(article);});$('adapt-content').textContent=productionPlan().requirements.some(r=>r.status==='preview_ready')?'Kanala özel taslakları hazırla':'Bekleyen üretim işlerini göster';$('adapt-content').disabled=!state.selected || state.stale;$('content-next').disabled=!state.selected || !state.adaptations || state.stale;
  $('creative-context').textContent=`${state.brief.identity||'Bu çalışma'} · ${state.brief.audience} · İstek: ${state.brief.description} · Demo grup ${state.batch}`;
  let back=$('previous-trio');if(!back){back=btn('Önceki üçlü',()=>{const old=state.history.pop();if(old){state.cards=old.cards;state.selected=old.selected;state.brief=old.brief;restoreBrief(old.brief);contentChanged();state.unlocked=2;renderCards();}});back.id='previous-trio';$('regenerate').after(back);}back.hidden=!state.history.length;syncLocks();
}
$('regenerate').addEventListener('click',makeCards);
let editing=null,edited=null;
function openEditor(c){editing=c;edited={...c};for(const [field,key] of [['edit-title','title'],['edit-message','message'],['edit-cta','cta'],['edit-x','x'],['edit-y','y']])$(field).value=c[key];$('editor-preview').replaceChildren(artwork(c));$('editor').showModal();}
for(const [field,key] of [['edit-title','title'],['edit-message','message'],['edit-cta','cta'],['edit-x','x'],['edit-y','y']])$(field).addEventListener('input',()=>{edited[key]=['x','y'].includes(key)?+$(field).value:$(field).value;$('editor-preview').replaceChildren(artwork(edited));});
$('editor-cancel').addEventListener('click',()=>$('editor').close());$('editor-save').addEventListener('click',()=>{if(!edited.title.trim()||!edited.cta.trim())return;editing.edits.push({title:editing.title,message:editing.message,cta:editing.cta,x:editing.x,y:editing.y});Object.assign(editing,edited);editing.revision++;contentChanged();renderCards();$('editor').close();});
function inputs(){return {budget:+$('budget').value,days:+$('duration').value,value:+$('order-value').value,margin:+$('margin').value,cpa:+$('cpa').value,capacity:+$('capacity').value,goal:$('goal').value,business:$('business').value,audience:$('audience').value,sector:$('sector').value,risk:$('risk').value,communication:$('communication').value,action:$('action').value,geo:{area:'district_city',radius:'radius_local',country:'nationwide'}[$('geo-mode').value],radius:+$('radius').value,region:$('region').value,start:$('start').value,measurement:$('measurement').value,fixture:hasCustomBrief()?'unknown':$('fixture').value,readiness:$('demo-readiness').value,video:$('video').checked && $('video-allowed').checked,catalog:$('catalog').checked,tracking:$('tracking').checked};}
function fxName(source){return source==='tcmb'?'TCMB gösterge satış':source==='ecb'?'ECB çapraz referans':'Tarihli araştırma örneği';}
function recommend(){
  if(!state.brief||state.briefDirty){$('decision-status').textContent='Önce isteğini kontrol edip Planını kur ile devam et.';return;}
  if(!$('plan-form').reportValidity())return;
  try{
    const i=inputs();
    state.plan=E.evaluate(i,D,i.fixture==='interactive'?S.forecast(i,D):null,window.YaparoSources?.getFx(sourceContext()));
    state.revision++;state.stale=false;state.contentBinding=null;state.adaptations=null;$('platform-previews').replaceChildren();state.unlocked=1;syncLocks();renderPlan();renderRequirements($('plan-production'));
    const text=hasCustomBrief()?'Elle yazdığın tercih kaydedildi. Otomatik kanal eşleştirmesi henüz yok; bütçe ayırmadık.':state.plan.interactive?'HAZIRLANMIŞ SENARYO: bölge, hedef, süre ve hazırlık için temsili değerler hesaplandı.':state.plan.bound?'27 Ekim 2026 tarihli TEMSİLİ SC01 verisi kullanıldı.':'Bu koşullara bağlı tahmin yok; bütçe önerilmedi.';
    $('decision-status').textContent=`Öneri ${state.revision} · ${text} Para birimi dönüşümü: ${fxName(state.plan.fx.source)} (${state.plan.fx.source_as_of}). Gerçek AI / reklam platformu sorgusu yapılmadı.`;
    if(!window.YaparoSources?.isCurrent(sourceContext()))window.YaparoSources?.contextChanged();
  }catch(err){state.stale=true;$('decision-status').textContent=err.message;}
}
$('recommend').addEventListener('click',recommend);
$('content-next').addEventListener('click',()=>{if(!state.selected||!state.adaptations||state.stale||state.contentBinding!==productionPlan().signature)return;state.unlocked=3;go(3);});
$('adapt-content').addEventListener('click',()=>{if(!state.selected||state.stale||state.contentBinding!==productionPlan().signature)return;const core=state.cards.find(c=>c.id===state.selected);state.adaptations=P.adapt(core,state.production.requirements);renderAdaptations();renderCards();$('production-status').textContent=`${state.adaptations.length} kanala özel metin / görsel demo taslağı hazırlandı. Bekleyen video ve diğer işler aşağıda açıkça gösterilir; hiçbir ücretli üretim yapılmadı.`;});
$('plan-form').addEventListener('input',e=>{if(!e.composedPath().includes($('recommended'))){invalidate();if(mode()==='organic'){state.stale=false;renderRequirements($('plan-production'));}}});$('plan-form').addEventListener('change',e=>{if(!e.composedPath().includes($('recommended'))){invalidate();if(mode()==='organic'){state.stale=false;renderRequirements($('plan-production'));}}});
function geoVisibility(){$('radius-field').hidden=$('geo-mode').value!=='radius';$('radius').disabled=$('radius-field').hidden;$('region').required=$('geo-mode').value!=='country';}
$('geo-mode').addEventListener('change',geoVisibility);geoVisibility();
function guide(row){$('guide-title').textContent=row.channel.name;const root=$('guide-body');root.replaceChildren();const pairs=[['Durum',row.amount?'Önerildi':row.owned?'Bütçe dışı aksiyon':row.eligible?'Koşullu / portföy dışında':'Bu koşullarda seçilmedi'],['Neden',row.reasons.map(x=>E.reasonText[x]).join(' · ')||'Anlamlı test ve tavan koşulları karşılandı.'],['Teknik minimum',row.platform===null?'Hesap / para birimi doğrulaması bekliyor':money(row.platform)],['Anlamlı test minimumu',money(row.useful)],['Faydalı tavan',row.cap===null?'Tahmin yok, hesaplanmadı':money(row.cap)],['Tavanın kaynağı','Temsili talep, toplam bütçe ve ortak işletme kapasitesi / marj sınırının en küçüğü'],['Uzman uygunluğu',`${row.score}/100 · başarı olasılığı değildir`],['Tahmin kaynağı / tarihi',`${row.f?.quality||'Yok'} · ${row.f?.updated||'Yok'} · yalnız SC01`],['Bu koşula bağlı mı?',state.plan.bound?'Evet, tarihli sentetik fixture':'Hayır: gerçek tahmin yenilemesi gerekli'],['Satın alma biçimi',row.channel.purchase],['Nerede işe yarar?',row.channel.best],['Hazırlık',row.channel.assets.join(' · ')],['Coğrafya araştırma notu',row.channel.geo],['Sınır',row.channel.note]];
  if(state.plan.interactive){pairs[7][1]=`${S.version} · ${row.f.updated} · hazırlanmış dinamik demo; piyasa verisi değil`;pairs[8][1]='Yalnız mevcut demo koşulları için türetilmiş; gerçek hedefleme / hesap onayı sağlamaz.';pairs.push(['Örnek hesap varsayımı',row.f.accountReady?'Bu senaryoda hazır varsayıldı; gerçek bağlantı yok':'Bu senaryoda hazır varsayılmadı']);}
  const dl=el('dl',undefined,'guide-dl');pairs.forEach(([k,v])=>dl.append(el('dt',k),el('dd',v)));root.append(dl);const det=el('details');det.append(el('summary','Puanın 8 boyutunu incele'));row.breakdown.forEach(x=>det.append(el('p',`${x.dimension}: ${x.score}/5 × %${x.weight} = ${x.points} puan`)));root.append(det);
  row.channel.sourceIds.forEach(id=>{const s=D.sources.find(s=>s.id===id);if(!s)return;const p=el('p',`${id} · ${s.title} · ${s.publisher} · araştırma kaynağı; bağımsız kontrol edilmedi`,'hint');if(/^https:\/\//.test(s.url)){const a=el('a','Kaynağı aç');a.href=s.url;a.target='_blank';a.rel='noopener noreferrer';p.append(' ',a);}root.append(p);});$('guide').showModal();}
$('guide-close').addEventListener('click',()=>$('guide').close());
function renderPlan(){const p=state.plan;if(!p)return;const stats=$('plan-summary');stats.replaceChildren();[['Toplam bütçe',money(p.total)],['Önerilen yatırım',money(p?.allocated||0)],['Ayrılmamış bütçe',money(p?.unallocated||0)]].forEach(([t,v])=>{const n=el('div',undefined,'summary-stat');n.append(el('span',t),el('strong',v));stats.append(n);});
  const upper=$('recommended'),lower=$('other-channels');upper.replaceChildren();lower.replaceChildren();
  const groups={};[['paid','Diğer reklam ürünleri'],['managed','Partner / yönetilen satın alma'],['owned','Reklam bütçesi dışındaki aksiyonlar']].forEach(([id,title])=>{const g=el('section',undefined,'catalog-group');g.append(el('h3',title));lower.append(g);groups[id]=g;});
  const ordered=[...p.rows].sort((a,b)=>b.amount-a.amount || b.score-a.score);
  ordered.forEach(r=>{const row=el('article',undefined,r.amount?'channel-row':'other-channel');row.dataset.channel=r.channel.id;const main=el('div',undefined,'channel-main');main.append(el('span',r.channel.family.slice(0,2),'channel-logo'));const info=el('div',undefined,'channel-info');info.append(el('h3',r.channel.name),el('p',r.amount?`${r.score}/100 uygunluk · ${money(r.useful)} test min. · ${money(r.cap)} tavan`:r.reasons.map(x=>E.reasonText[x]).join(' · ')||'Uygun aday; şu an pay ayrılmadı'));main.append(info);row.append(main);
    const controls=el('div',undefined,'channel-allocation');if(r.amount){const input=el('input');input.type='number';input.min='0';input.max=(r.cap/100).toFixed(2);input.step='0.01';input.value=(r.amount/100).toFixed(2);input.setAttribute('aria-label',`${r.channel.name} bütçesi TL`);input.addEventListener('change',()=>{try{E.manual(p,r.channel.id,Math.round(Number(input.value)*100));allocationChanged();renderPlan();$('decision-status').textContent='Manuel tutar uygulandı. Yeniden öner düğmesi bu değişikliği sıfırlar.';}catch(err){$('decision-status').textContent=err.message;input.value=(r.amount/100).toFixed(2);}});controls.append(input,el('span',`TL · %${percent(r.amount,p.total)}`));}
    else if(r.eligible){controls.append(btn('Plana ekle',()=>{try{E.manual(p,r.channel.id,r.useful);allocationChanged();renderPlan();}catch(err){$('decision-status').textContent=err.message;}},'secondary'));}
    else controls.append(el('span',r.owned?'Bütçe dışı':r.reasons.includes('policy_review')?'İnceleme':'Eksik koşul','status'));
    const book=btn('ⓘ',()=>guide(r),'book-button');book.setAttribute('aria-label',`${r.channel.name} neden ve koşullar`);controls.append(book);row.append(controls);
    if(r.amount){
      const slider=el('input');slider.type='range';slider.min='0';slider.max=String(r.cap);slider.step='1';slider.value=String(r.amount);slider.className='share-slider';slider.setAttribute('aria-label',`${r.channel.name} payını ayarla`);
      slider.addEventListener('change',()=>{try{E.manual(p,r.channel.id,+slider.value);allocationChanged();renderPlan();$('decision-status').textContent='Payı değiştirdin. Minimum ve tavan korundu; kalan tutar ayrılmamış bütçede.';}catch(err){$('decision-status').textContent=err.message;slider.value=String(r.amount);}});
      row.append(slider);upper.append(row);
    }else groups[r.owned?'owned':/managed|partner|creator/.test(r.channel.purchase)?'managed':'paid'].append(row);
  });if(!p.allocated)upper.append(el('p',p.blocked?'Bu istekte önce belge / politika incelemesi gerekli. İçerik taslağın korunuyor.':'Bu koşullarda uygulanabilir bir bütçe önerisi yok. Eksik koşulları aşağıdan inceleyebilirsin.','empty-state'));
  $('why-plan').replaceChildren(el('strong','Bu plan neden böyle?'),el('p',p.blocked?'İnceleme kapısı kanal puanından önce gelir; kullanıcı beyanı belge onayı sayılmaz.':p.interactive?`Bu senaryoda ${label('goal').toLocaleLowerCase('tr-TR')} hedefi ve ${label('audience').toLocaleLowerCase('tr-TR')} için hesap / içerik varsayımları değerlendirildi. Bütçe önce anlamlı testlere, sonra puan ve örnek talep tavanlarına göre dağıtıldı. Pay almayana nedenini ⓘ düğmesinden sorabilirsin.`:p.bound?'Kanallara önce anlamlı test tutarı ayrıldı. Kalan tutar uzman puanının karesiyle, talep ve ortak işletme tavanlarına kadar dağıtıldı. Kalan bütçeyi harcamak zorunda değilsin.':'Örnek Kadıköy tahmini başka bölgeye, hedefe, tarihe veya kitleye taşınmadı. Gerçek hesaptan yeni bir tahmin alınmadan kesin rakam gösterilmez.'),el('small',`${D.version} · ${p.interactive?S.version+' · temsili senaryo':'8 boyutlu uzman başlangıç puanları'} · gerçek tahmin ve garanti yok · AI çağrısı yok`));
  if(p.interactive)p.rows.filter(r=>r.amount).forEach(r=>{const traffic=r.f.cpc>0?Math.floor(r.amount/100/r.f.cpc):0,impressions=r.f.cpm>0?Math.floor(r.amount/100/r.f.cpm*1000):null;const text=`TEMSİLİ ÖRNEK · ${impressions?`${Math.floor(impressions*.75).toLocaleString('tr-TR')}–${Math.floor(impressions*1.25).toLocaleString('tr-TR')} gösterim · `:''}${Math.floor(traffic*.7)}–${Math.floor(traffic*1.3)} tıklama; gerçek tahmin değildir.`;upper.querySelector(`[data-channel="${r.channel.id}"]`).append(el('p',text,'simulated-results'));});
}
$('plan-form').addEventListener('submit',e=>{e.preventDefault();if(mode()!=='organic' && (!state.plan||state.stale)){$('decision-status').textContent='Koşullar değişti. Önce dağılımı yeniden öner.';return;}const production=productionPlan();if(!production.requirements.length){$('plan-next-status').textContent='Önce uygun bir ücretli kanal veya organik paylaşım alanı seç. Koşulları eksik kanal için içerik üretmiyoruz.';return;}state.production=production;state.contentBinding=production.signature;state.stale=false;state.unlocked=2;if(!state.cards.length)makeCards();renderRequirements($('production-requirements'));renderCards();$('production-status').textContent='Üretim ihtiyaçların doğrulandı. Bir fikir seçip kanala özel taslakları hazırla.';go(2);});
function review(){
  const p=state.plan,c=state.cards.find(c=>c.id===state.selected),root=$('review');root.replaceChildren();if(!c)return;
  const visual=el('div');visual.append(artwork(c));const body=el('section',undefined,'review-panel'),dl=el('dl');
  const pairs=[['Çalışma türü',label('journey-mode')],['İletişim işi',label('communication')],['İstek',state.brief.description],['Kitle',state.brief.audience],['İstenen aksiyon',label('action')],['Kendi tanımların',Object.entries(state.brief.custom||{}).map(([key,value])=>`${({communication:'Amaç',business:'İş modeli',sector:'Alan',action:'Aksiyon',destination:'Yönlendirme'})[key]||D.questions.find(q=>q.id===key)?.label||key}: ${value}`).join(' · ')||'Standart seçenekler'],
    ['Yönlendirme',destinationSummary(state.brief.destination)],['Yaratıcı rota',`${c.angle} · ${c.tone} · ortak yaratıcı fikir · revizyon ${c.revision}`],['Mesaj / CTA',`${c.title} · ${c.message} · ${c.cta}`],['Reklam hedefi',label('goal')],
    ['Bölge',p?`${p.input.geo==='nationwide'?'Türkiye':p.input.region}${p.input.geo==='radius_local'?` · ${p.input.radius} km`:''} · hedefleme doğrulanmadı`:'Ücretli hedefleme yok'],
    ['Önerilen bütçe',money(p?.allocated||0)],['Ayrılmamış bütçe',money(p?.unallocated||0)],
    ['Kanal planı',p?p.rows.filter(r=>r.amount).map(r=>`${r.channel.name}: ${money(r.amount)}`).join(' · ')||'Koşullar bekliyor':'Yalnız organik paylaşım · medya bütçesi yok'],
    ['Veri durumu',!p?'Organik demo · gerçek AI / yayın bağlantısı yok':p.interactive?'Hazırlanmış dinamik demo · örnek hesaplar ve maliyetler · gerçek tahmin değil':'Tarihli SC01 temsili verisi · gerçek sonuç / getiri garantisi yok'],
    ['Kur kaynağı',p?`${fxName(p.fx.source)} · ${p.fx.source_as_of} · 1 USD = ${p.fx.rate.toLocaleString('tr-TR',{maximumFractionDigits:8})} TRY · işlem kuru değildir`:'Organik içerik için medya dönüşümü yok'],
    ['Kur kayıt kimliği',p?.fx.snapshot_id||'Canlı kaynak kaydı yok veya kullanılmıyor'],
    ['Üretim ve hizmet bedeli','Bu prototipte hesaplanmaz; medya bütçesinden ayrıdır'],['Yayın hazırlığı','KAPALI · gerçek hesap, izin, ölçüm ve platform tahminleri bekliyor']];
  pairs.forEach(([k,v])=>dl.append(el('dt',k),el('dd',v)));body.append(dl);root.append(visual,body);const productionReview=el('section',undefined,'production-requirements');renderRequirements(productionReview);root.append(productionReview);root.append(el('p',`${state.adaptations?.filter(x=>x.status==='preview_ready').length||0} kanala özel demo taslağı · bekleyen üretim işleri ve maliyetleri doğrulanmadı. Yayın kapalı.`));$('finish-status').textContent='';$('finish').disabled=false;
}
$('finish').addEventListener('click',()=>{if(state.stale){$('finish-status').textContent='Kaynak veya plan koşulları değişti. Planı yeniden değerlendir.';return;}$('finish-status').textContent='Taslak kontrol edildi. Kalıcı kampanya kaydı, AI çağrısı, ödeme ve reklam yayını yapılmadı.';$('finish').disabled=true;});
function chat(t){const log=$('chat-log');log.append(el('div',t,'user-message'));const intent=S.intent(t),selected=state.cards.find(c=>c.id===state.selected);let answer='',action=null,actionLabel='Öneriyi uygula';
  if(intent.type==='patch'){answer=`Şu değişikliği hazırladım: ${Object.entries(intent.patch).map(([k,v])=>`${({budget:'Bütçe (TL)',duration:'Süre (gün)',region:'Bölge',radius:'Yarıçap (km)','geo-mode':'Konum türü'})[k]}: ${v}`).join(' · ')}. İçeriğin korunacak; uygularsan örnek dağılım yeniden hesaplanacak.`;action=()=>{applyPatch(intent.patch);if(mode()!=='organic')recommend();else state.stale=false;if(state.step>1)go(1);};}
  else if(intent.type==='simplify'||intent.type==='alternative'){answer=selected?`${selected.angle} yönünü koruyup ${intent.type==='simplify'?'daha kısa ve sade':'aynı tarzda alternatif'} bir metin hazırlayabilirim. Önceki metni Geri al ile geri getirebilirsin.`:'Önce bir içerik yönü seç. Sonra o içeriğe özel değişikliği hazırlayabilirim.';if(selected)action=()=>{selected.edits.push({title:selected.title,message:selected.message,cta:selected.cta,x:selected.x,y:selected.y});Object.assign(selected,S.alternative(selected,state.brief));if(intent.type==='simplify'){selected.message=selected.message.split(';')[0].split('.')[0]+'.';selected.title=selected.title.split('.')[0]+'.';}selected.revision++;contentChanged();renderCards();if(state.step===3)go(2);};}
  else if(intent.type==='regenerate'){answer=state.brief?'Aynı istek ve kimlikle üç farklı yön hazırlayacağım. Önceki üçlünü geri getirebilirsin.':'Önce isteğini soldaki alana yaz; ardından üç yönü hazırlayalım.';if(state.brief&&!state.stale&&state.contentBinding===productionPlan().signature)action=()=>{makeCards();go(2);};}
  else if(intent.type==='explain'){answer=state.plan?`${state.brief?.identity||'Bu çalışma'} için ${money(state.plan.allocated)} önerildi, ${money(state.plan.unallocated)} ayrılmadı. ${state.plan.rows.filter(r=>r.amount).map(r=>`${r.channel.name}: ${money(r.amount)}, tavanı ${money(r.cap)}`).join(' · ')}. ${state.stale?'Koşullar değişti; eski sonuç güncel değil. ':''}Bu tutarlar hazırlanmış demo varsayımlarıdır. Önce koşullar, sonra test minimumu, puan ve tavanlar uygulanır.`:'Önce hedef, bölge ve bütçene göre kanalları, sonra onların içerik ihtiyaçlarını belirleriz. İstersen bütçe 5000, 14 gün gibi bir değişiklik yazabilirsin.';}
  else if(intent.type==='policy'){answer='İçerik fikrini taslak olarak koruyabiliriz. Gerekli belge / politika kontrolü tamamlanmadan ücretli öneri açılmaz. Bu demoda bir mesaj veya kutucuk belge doğrulaması yerine geçmez.';}
  else if(intent.type==='brief'){answer=`Bunu ${intent.profile.name.toLocaleLowerCase('tr-TR')} çalışması olarak ele alabilirim. Mesajını istek alanına, ilgili seçimleri örnek profile yerleştireceğim. Sonra seçenekleri kontrol edip içerik aşamasına geçebilirsin.`;action=()=>{loadExample(intent.profile,t);go(0);};actionLabel='İsteğime yerleştir';}
  else {answer=[`Kısa anlatımın hazır. Şimdi “${label('communication')}” seçimini ve istediğin aksiyonu kontrol edip planını açabilirsin.`,`Önce yayın alanlarını ve gereken formatları belirliyoruz. Ücretli reklamda bütçe ve hedefini, organikte paylaşım alanlarını seç.`,`Üç kart ortak yaratıcı fikirdir. Birini seçtikten sonra yalnız planlanan alanlar için taslakları hazırla. Video üretimi bu prototipte bağlı değil.`,`İçeriğin ve planın bir arada. Taslağı tamamlayabilir veya planına geri dönebilirsin; gerçek reklam yayını açılmaz.`][state.step];}
  const message=el('div',answer,'assistant-message');if(action){const proposalContext=assistantContext();const apply=btn(actionLabel,()=>{if(proposalContext!==assistantContext()){apply.disabled=true;apply.textContent='Koşullar değişti · Yeniden iste';return;}action();apply.disabled=true;apply.textContent='✓ Uygulandı';},'secondary');message.append(apply);}message.append(el('small','Hazırlanmış yerel demo yanıtı · canlı AI değildir'));log.append(message);while(log.children.length>24)log.firstElementChild.remove();log.scrollTop=log.scrollHeight;
}
function assistantContext(){return JSON.stringify({step:state.step,productionSignature:productionPlan().signature,brief:briefObject(),selected:state.selected,cards:state.cards.map(c=>[c.id,c.revision]),inputs:inputs(),revision:state.revision,amounts:state.plan?.rows.map(r=>[r.channel.id,r.amount])});}
$('chat-form').addEventListener('submit',e=>{e.preventDefault();const t=$('chat-input').value.trim();if(t)chat(t);$('chat-input').value='';});
$('helper-toggle').addEventListener('click',()=>{const open=$('helper-panel').classList.toggle('mobile-open');$('helper-toggle').setAttribute('aria-expanded',String(open));if(open)$('chat-input').focus();});
window.YaparoStudio = {getSnapshot:()=>structuredClone({mode:mode(),production:state.production,adaptations:state.adaptations,contentBinding:state.contentBinding,brief:state.brief,creative:state.cards.find(c=>c.id===state.selected),plan:state.plan,stale:state.stale,revision:state.revision})};
// Keep campaign conditions and their consequences side by side, not in a long column.
const planForm=$('plan-form'), planControls=el('div'), planResults=el('div');planControls.id='plan-controls';planResults.id='plan-results';
let resultSection=false;[...planForm.children].forEach(node=>{if(node.classList.contains('form-footer'))return;if(node.classList.contains('decision-toolbar'))resultSection=true;(resultSection?planResults:planControls).append(node);});planForm.prepend(planControls,planResults);
['order-value','margin','cpa','capacity'].forEach(id=>$(id).required=true);
$('goal').addEventListener('change',()=>state.goalManual=true);
function applyPatch(patch){for(const [id,value] of Object.entries(patch)){if($(id))$(id).value=value;}geoVisibility();invalidate();}
function restoreBrief(b){if(!b)return;primeBriefSelections();$('journey-mode').value=b.mode||'paid';for(const [id,key] of [['communication','communication'],['business','business'],['action','action'],['brief','description'],['audience-description','audience'],['sector','sector'],['risk','risk'],['identity','identity'],['message','message']])$(id).value=b[key]||'';state.answers={...b.branch};state.destination=b.destination?structuredClone(b.destination):null;if(b.destination)state.answers.S1_B02=b.destination.type;state.briefDirty=false;syncBriefFlow(b.custom||{});renderStartChoices();}
function loadExample(p,description){state.destination=null;primeBriefSelections();state.goalManual=false;const isB2B=p===S.profiles.saas;const examples={coffee:'Sentetik örnek: İzmir’deki Örnek Kafe’de taze hazırladığımız kahveleri tanıtmak, yakındaki kişileri hafta sonu bir molaya davet etmek istiyorum.',fashion:'Sentetik örnek: Kadıköy’deki Örnek Butik’in özgün tasarımlarını tanıtmak ve insanları koleksiyonu mağazada görmeye davet etmek istiyorum.',software:'Sentetik örnek: Örnek Yazılım, küçük ekiplerin görevlerini tek yerde takip ettiği bir araç. İşletme sahiplerinden ürün tanışması için form talebi toplamak istiyorum.',home:'Sentetik örnek: Ankara’daki Örnek Ev Hizmeti için çalışma bölgemdeki insanlara bakım hizmetimizi anlatmak, önce telefonla ihtiyaçlarını öğrenmek istiyorum.',event:'Sentetik örnek: İzmir’de yetişkinlere yönelik bir seramik atölyesi düzenliyoruz. Etkinlik tarihini daha sonra belirleyip katılım bilgisi isteyenleri başvuruya yönlendirmek istiyorum.'};
  $('communication').value=p.communication||'product_service_intro';$('business').value=p.business;$('action').value=p.action;$('sector').value=p.sector;$('audience').value=p.audience;$('goal').value=p.goal;$('brief').value=description||examples[p.theme]||'Sentetik örnek: Yeni fikrimi tanıtmak, ilgilenen kişileri daha fazla bilgi almaya davet etmek istiyorum.';$('audience-description').value=isB2B?'Küçük ve orta ölçekli ekiplerin karar vericileri':'Bölgedeki ilgili yetişkinler';$('identity').value=({coffee:'Örnek Kafe',fashion:'Örnek Butik',software:'Örnek Yazılım',home:'Örnek Ev Hizmeti',event:'Örnek Atölye'})[p.theme]||'Örnek Çalışma';$('message').value='';state.answers={S1_B02:({visit_store:'physical_store',visit_website:'own_website',fill_form:'lead_form',call:'whatsapp_phone',download_app:'app',register_event:'lead_form',book_appointment:'lead_form',message_whatsapp:'whatsapp_phone'})[p.action]||''};$('fixture').value='interactive';$('demo-readiness').value='core';$('geo-mode').value=isB2B?'country':'area';$('region').value=p.theme==='home'?'Ankara':p.theme==='fashion'?'İstanbul, Kadıköy':'İzmir';$('budget').value=isB2B?'20000':'3000';$('order-value').value=isB2B?'10000':'500';$('margin').value=isB2B?'60':'40';$('cpa').value=isB2B?'600':'100';$('capacity').value=isB2B?'10':'20';$('duration').value='7';$('video').checked=false;$('video-allowed').checked=false;$('catalog').checked=false;$('tracking').checked=false;syncBriefFlow();const type=$('q-S1_B02').value;if(type){state.destination={type,values:type==='physical_store'?{address:'Örnek Mahallesi, Örnek Sokak No: 1 · sentetik adres'}:type==='whatsapp_phone'?{phone:'+90 555 000 00 00'}:{url:`https://ornek.example/${type}`}};renderDestinationDetails();}renderStartChoices();geoVisibility();briefChanged();}
for(const [key,text] of [['cafe','☕ Kafe açılışı'],['fashion','◈ Butik koleksiyonu'],['saas','▤ B2B yazılım'],['home','⌂ Yerel hizmet'],['event','✦ Atölye daveti']])$('scenario-examples').append(btn(text,()=>loadExample(S.profiles[key]),'scenario-chip'));
const suggestions=el('div',undefined,'helper-suggestions');for(const text of ['Daha sade olsun','Bütçe 5000, 14 gün','Neden bu kanallar?'])suggestions.append(btn(text,()=>chat(text),'scenario-chip'));$('chat-form').before(suggestions);
function mode(){return $('journey-mode').value;}
function organicPlatforms(){return [...document.querySelectorAll('[name="organic-platform"]:checked')].map(n=>n.value);}
function productionPlan(){return P.build({mode:mode(),plan:state.plan,organicPlatforms:organicPlatforms(),videoAllowed:$('video-allowed').checked,videoAvailable:$('video').checked});}
function allocationChanged(){state.contentBinding=null;state.adaptations=null;$('adapt-content').disabled=true;$('content-next').disabled=true;$('platform-previews').replaceChildren();$('production-status').textContent='Kanal dağılımı değişti. Üretim planını yeniden doğrula.';state.unlocked=1;syncLocks();renderRequirements($('plan-production'));}
function renderRequirements(root){const result=productionPlan();root.replaceChildren(el('h2','Neyi, nerede, neden hazırlayacağız?'));const list=el('ul');for(const r of result.requirements){list.append(el('li',`${r.placement} · ${r.quantity} ${r.medium==='text'?'metin':r.medium==='image'?'görsel':r.medium==='video'?'video':'iş'} · ${r.purpose} · ${r.status==='preview_ready'?'Yerel demo taslağı hazırlanabilir':r.status==='blocked_material'?'Materyal / video tercihi eksik':'Üretim bağlantısı ve maliyet doğrulaması bekliyor'}`));}root.append(list,el('p',result.disclaimer),el('p','Üretim / hizmet bedeli medya bütçesinden ayrıdır. Bu taslakta fiyat hesaplanmaz; yeni ücretli üretim onayı alınmış sayılmaz.'));if(!result.requirements.length)root.append(el('p','Henüz uygun bir yayın alanı yok; boş plan için içerik üretilmez.'));}
function renderAdaptations(){const root=$('platform-previews');root.replaceChildren();const core=state.cards.find(c=>c.id===state.selected);for(const preview of state.adaptations||[]){const row=el('article',undefined,'platform-preview');row.dataset.medium=preview.medium;row.append(el('h2',preview.label||preview.placement||preview.requirementId));if(preview.medium==='image'&&preview.status==='preview_ready')row.append(artwork(core));row.append(el('p',preview.status==='preview_ready'?'Kanala özel hazırlanmış demo · yayına hazır değildir':'Bekliyor · video / özel üretim burada yapılmaz'));for(const text of preview.headlines||[])row.append(el('strong',text),el('br'));for(const text of preview.descriptions||[])row.append(el('p',text));if(preview.title&&preview.medium!=='text')row.append(el('strong',preview.title));if(preview.body)row.append(el('p',preview.body));if(preview.caption)row.append(el('p',preview.caption));if(preview.notice)row.append(el('small',preview.notice));root.append(row);}for(const pending of state.production.requirements.filter(r=>r.status!=='preview_ready')){const row=el('article',undefined,'platform-preview');row.append(el('h2',pending.placement),el('p',pending.purpose),el('strong',pending.status==='blocked_material'?'Video tercihi / materyal eksik':'Üretim bağlantısı, haklar ve maliyet onayı bekliyor'));root.append(row);}}
function configureJourney(){const organic=mode()==='organic';document.body.classList.toggle('organic-only',organic);$('plan-controls').hidden=organic;$('plan-results').hidden=organic;for(const n of $('plan-controls').querySelectorAll('input,select,textarea'))n.disabled=organic;$('organic-controls').hidden=mode()==='paid';if(!organic)geoVisibility();$('plan-next-status').textContent='';}
// Material preferences and organic destinations apply to both routes, outside paid controls.
const material=el('div',undefined,'production-requirements');material.id='material-controls';material.append(el('h2','Mevcut materyallerin ve içerik tercihin'));for(const id of ['video-allowed','video'])material.append($(id).closest('label'));material.append(el('p','Fotoğraf / dosya yükleme bağlı değil. Video yoksa video gerektiren ücretli kanallar önerilmez; üretim ve maliyet onayı sonradan ayrıca gerekir.'));planForm.prepend($('organic-controls'),material);planForm.append($('plan-production'),$('plan-next-status'),planForm.querySelector('.form-footer'));configureJourney();
// Single-screen brief: contextual lists and explicit manual Other, no sub-journey.
const manualBriefFields={business:'business',sector:'sector',destination:'q-S1_B02'};
const manualBriefLabels={business:'Bunu nasıl sunduğunu yaz',sector:'Faaliyet alanını yaz',destination:'Yönlendirme yerini yaz'};
function isBriefOther(key){const id=manualBriefFields?.[key]||key;return $(id)?.value===(key==='sector'?'other':'__other__');}
function briefCustom(){const result={};for(const key of Object.keys(manualBriefFields))if(isBriefOther(key))result[key]=$(`${key}-other`).value.trim();for(const n of document.querySelectorAll('.branch-other-text:enabled'))result[n.dataset.customQuestion]=n.value.trim();return result;}
function hasCustomBrief(){return Object.keys(manualBriefFields).some(isBriefOther)||!!document.querySelector('.branch-other-text:enabled');}
function setBriefOptions(select,options,value='',enabled=true){select.replaceChildren();const blank=el('option',enabled?'Seçimini yap':'Önce ilgili üst seçimi yap');blank.value='';select.append(blank);for(const o of options){const n=el('option',o.label);n.value=o.value;select.append(n);}const otherValue=select.id==='sector'?'other':'__other__';if(!['communication','action'].includes(select.id)){if(!options.some(o=>o.value===otherValue)){const other=el('option','Diğer · kendim yazacağım');other.value=otherValue;select.append(other);}else select.querySelector('option[value="other"]').textContent='Diğer · kendim yazacağım';}select.value=[...select.options].some(o=>o.value===value)?value:'';select.disabled=!enabled;}
function destinationApplies(){return B.destinationApplies($('communication').value,$('action').value,D);}
function readDestination(){if(!destinationApplies()||!$('q-S1_B02').value){const finance=state.answers.S1_F04;if($('communication').value==='fundraising'&&['official_site','authorized_platform'].includes(finance?.channel))return {type:'own_website',values:{url:finance.url||''},version:'yaparo-destination-v1'};return null;}const type=$('q-S1_B02').value,values={};if(state.destination?.type===type)for(const field of B.destinationFields(type,$('action').value)){const value=state.destination.values?.[field.key]?.trim();if(value)values[field.key]=value;}return {type,values,version:'yaparo-destination-v1'};}
function storeDestinationType(){const type=$('q-S1_B02').value;if(destinationApplies()&&D.options.some(o=>o.questionId==='S1_B02'&&o.value===type))state.answers.S1_B02=type;else delete state.answers.S1_B02;}
function renderDestinationDetails(){const root=$('destination-details'),type=$('q-S1_B02').value;root.replaceChildren();if(!destinationApplies()||!type){state.destination=null;root.hidden=true;return;}if(state.destination?.type!==type)state.destination={type,values:{}};const fields=B.destinationFields(type,$('action').value);root.hidden=!fields.length;for(const field of fields){const box=el('div'),label=el('label',field.label),input=el(field.type==='textarea'?'textarea':'input');input.id=`destination-${field.key}`;label.htmlFor=input.id;if(input.tagName==='INPUT')input.type=field.type||'text';input.required=!!field.required;input.maxLength=field.maxLength||2048;input.placeholder=field.placeholder||'';input.value=state.destination.values?.[field.key]||'';input.addEventListener('input',()=>{for(const n of root.querySelectorAll('input,textarea'))n.setCustomValidity('');if(input.value.trim())state.destination.values[field.key]=input.value;else delete state.destination.values[field.key];});box.append(label,input);root.append(box);}if(type==='physical_store')root.append(el('p','Bu adres ziyaret edilecek yeri belirtir. Reklamın gösterileceği bölgeyi plan adımında ayrıca seçersin.','hint'));}
function validateDestination(){const destination=readDestination();if(!destination)return true;const errors=B.validateDestination(destination.type,destination.values,$('action').value);for(const [key,message] of Object.entries(errors)){const input=$(`destination-${key}`)||$('destination-details').querySelector('input,textarea');$('brief-flow-status').textContent=message;if(input){input.setCustomValidity(message);input.reportValidity();input.focus();}return false;}return true;}
function destinationSummary(destination){if(!destination)return 'Yönlendirme belirtilmedi';if(destination.type==='none')return 'Yönlendirme yok · mesajı görmesi yeterli';const kind=D.options.find(o=>o.questionId==='S1_B02'&&o.value===destination.type)?.label||({social_profile:'Sosyal medya profili / içerik',__other__:'Kendi yönlendirme tanımın'})[destination.type]||'Yönlendirme';return [kind,...Object.values(destination.values||{})].join(' · ');}
function refreshManualBrief(){for(const [key,id] of Object.entries(manualBriefFields)){const active=isBriefOther(key)&&!$(id).disabled;const box=$(`${key}-other-field`),input=$(`${key}-other`);box.hidden=!active;input.disabled=!active;input.required=active;if(!active){input.value='';input.setCustomValidity('');}}const custom=hasCustomBrief();$('brief-flow-status').textContent=custom?'Diğer açıklaman çalışma notuna eklenir. Otomatik kanal eşleştirmesi doğrulanana kadar ücretli bütçe önerilmez.':'';}
function updateBriefActions(desiredDestination=null){const businessCopy={local_retail:'Mağazamdan / iş yerimden',local_service:'Randevu veya hizmet veriyorum',ecommerce_dtc:'Kendi sitemde ürün satıyorum',marketplace_seller:'Pazaryerlerinde ürün satıyorum',b2b_leadgen:'Şirketlere ürün veya hizmet sunuyorum',saas_subscription:'Dijital hizmet / üyelik sunuyorum',mobile_app:'Bir mobil uygulamam var',event:'Etkinlik / bilet sunuyorum',nonprofit_fundraising:'Sosyal fayda / yardım çalışması',employer_recruitment:'Kendi ekibim için',media_creator:'İçerik veya yayın paylaşıyorum'};for(const option of $('business').options)if(businessCopy[option.value])option.textContent=B.contextBank($('communication').value,$('action').value)?.labels?.[option.value]||businessCopy[option.value];const comm=$('communication').value,old=$('action').value;const options=D.options.filter(o=>o.questionId==='S1_Q04'&&B.intentActions(comm).includes(o.value));setBriefOptions($('action'),options,old,!!comm);const applicable=destinationApplies(),dest=$('q-S1_B02'),current=desiredDestination??dest.value;setBriefOptions(dest,B.destinations($('action').value,D),current,applicable);$('destination-field').hidden=!applicable;dest.required=applicable;if(!applicable)dest.value='';storeDestinationType();renderDestinationDetails();$('action-context').textContent='';}
function renderContextBank(){const bank=B.contextBank($('communication').value,$('action').value);if(!bank)return;document.querySelector('label[for="business"]').textContent=bank.business;document.querySelector('label[for="sector"]').textContent=bank.sector;$('context-form').querySelector('.context-heading strong').textContent=bank.title;$('business-other').previousElementSibling.textContent=bank.business.replace(/\?$/,'')+' · kendi tanımın';$('sector-other').previousElementSibling.textContent=bank.sector.replace(/\?$/,'')+' · kendi tanımın';}
function primeBriefSelections(){for(const [id,q] of [['communication','S1_Q01'],['business','S3_Q02'],['sector','S3_Q03'],['action','S1_Q04']])setBriefOptions($(id),D.options.filter(o=>o.questionId===q));}
function syncBriefFlow(custom=null){if(custom)state.branchCustom=Object.fromEntries(Object.entries(custom).filter(([key])=>D.questions.some(q=>q.id===key)));const comm=$('communication').value,business=$('business').value,sector=$('sector').value;setBriefOptions($('communication'),D.options.filter(o=>o.questionId==='S1_Q01'),comm);const businesses=comm==='__other__'?D.options.filter(o=>o.questionId==='S3_Q02'):B.businesses(comm,D,$('action').value);setBriefOptions($('business'),businesses,business,!!comm);const currentBusiness=$('business').value;const sectors=currentBusiness==='__other__'?D.options.filter(o=>o.questionId==='S3_Q03'&&(!B.contextBank(comm,$('action').value)?.sectors||B.contextBank(comm,$('action').value).sectors.includes(o.value))):B.sectors(comm==='__other__'?'unsure':comm,currentBusiness,D,$('action').value);setBriefOptions($('sector'),sectors,sector,!!comm&&!!currentBusiness);const destination=Object.hasOwn(state.answers,'S1_B02')?state.answers.S1_B02:$('q-S1_B02').value;updateBriefActions(destination);renderContextBank();branches();refreshManualBrief();if(custom)for(const [key,text] of Object.entries(custom))if(Object.hasOwn(manualBriefFields,key)&&isBriefOther(key))$(`${key}-other`).value=text;}
function validateBrief(){if(!startRoute()||!B.intentActions($('communication').value).includes($('action').value)){$('brief-flow-status').textContent='Önce ne yapmak istediğini ve gören kişinin ne yapmasını beklediğini seç.';$('purpose-choices').querySelector('button')?.focus();return false;}for(const id of Object.values(manualBriefFields)){const select=$(id);if(!select.disabled&&!select.value){select.focus();$('brief-flow-status').textContent='Devam etmek için ilgili seçimi tamamla.';return false;}}for(const [key] of Object.entries(manualBriefFields)){const input=$(`${key}-other`);if(isBriefOther(key)&&!input.disabled&&(!input.value.trim()||input.value.length>200)){input.setCustomValidity('Kendi tanımını 1–200 karakterle yaz.');input.reportValidity();return false;}}for(const input of document.querySelectorAll('.branch-other-text:enabled'))if(!input.value.trim()){input.setCustomValidity('Diğer seçimini 1–200 karakterle açıkla.');input.reportValidity();return false;}return validateDestination();}
for(const [key,id] of Object.entries(manualBriefFields)){const box=el('div',undefined,'brief-custom');box.id=`${key}-other-field`;box.hidden=true;const label=el('label',manualBriefLabels[key]);label.htmlFor=`${key}-other`;const input=el('input');input.id=`${key}-other`;input.maxLength=200;input.disabled=true;input.addEventListener('input',()=>input.setCustomValidity(''));box.append(label,input);$(id).after(box);}
const destinationDetails=el('div',undefined,'destination-details');destinationDetails.id='destination-details';destinationDetails.hidden=true;$('destination-field').append(destinationDetails);
for(const id of ['communication','business','sector'])$(id).addEventListener('change',()=>{syncBriefFlow();renderStartChoices();});
$('q-S1_B02').addEventListener('change',()=>{storeDestinationType();renderDestinationDetails();refreshManualBrief();});$('action').addEventListener('change',()=>{updateBriefActions();refreshManualBrief();renderStartChoices();});
for(const id of ['communication','business','sector','action'])$(id).value='';syncBriefFlow();
// The first screen asks only the two decisions people naturally make: intent and
// expected response. Detailed fields appear afterwards and stay editable.
const startRoutes=[
  {communication:'product_service_intro',kinds:['product_service_intro','launch'],label:'Bir marka, ürün veya hizmeti tanıtmak'},
  {communication:'sale_promotion',label:'Satış yapmak veya kampanya duyurmak'},
  {communication:'event',label:'Etkinliğe katılım almak'},
  {communication:'lead_request',label:'Talep, randevu veya görüşme almak'},
  {communication:'recruitment',label:'İşe alım için başvuru almak'},
  {communication:'fundraising',label:'Yardım veya bağış çağrısı yapmak'},
  {communication:'announcement',kinds:['announcement','celebration'],label:'Duyuru, kutlama veya güncelleme paylaşmak'},
  {communication:'membership',kinds:['membership','education'],label:'Topluluk, eğitim veya üyelik büyütmek'},
  {communication:'reputation',kinds:['reputation','public_issue'],label:'İtibar veya kamuoyu mesajı vermek'}
];
function startRoute(){return startRoutes.find(route=>(route.kinds||[route.communication]).includes($('communication').value));}
function choiceButton(text,selected,onClick){const b=btn(text,onClick,'choice-button');b.setAttribute('role','radio');b.setAttribute('aria-checked',String(selected));b.tabIndex=selected?0:-1;if(selected)b.classList.add('selected');b.addEventListener('keydown',event=>{if(!['ArrowRight','ArrowDown','ArrowLeft','ArrowUp','Home','End'].includes(event.key))return;event.preventDefault();const nodes=[...b.parentElement.children],i=nodes.indexOf(b),next=event.key==='Home'?0:event.key==='End'?nodes.length-1:(i+(['ArrowLeft','ArrowUp'].includes(event.key)?-1:1)+nodes.length)%nodes.length;nodes[next].focus();nodes[next].click();});return b;}
function renderStartChoices(){const focused=document.activeElement?.dataset,focusKey=focused?.purpose?'purpose':focused?.action?'action':null,focusValue=focusKey?focused[focusKey]:null;const purpose=$('purpose-choices'),actions=$('action-choices'),route=startRoute();purpose.replaceChildren(...startRoutes.map(item=>{const b=choiceButton(item.label,item===route,()=>{if(item===startRoute())return;primeBriefSelections();$('communication').value=item.communication;$('business').value='';$('sector').value='';$('action').value='';state.answers={};state.branchCustom={};syncBriefFlow();briefChanged();renderStartChoices();});b.dataset.purpose=item.communication;return b;}));if(!route)purpose.firstElementChild.tabIndex=0;
  const ready=!!route&&!!$('action').value;$('action-choice-block').hidden=!route;$('context-form').hidden=!ready;$('brief-submit').disabled=!ready;$('risk').closest('details').hidden=!ready;actions.replaceChildren();if(!route)return;const available=B.intentActions($('communication').value).map(value=>D.options.find(o=>o.questionId==='S1_Q04'&&o.value===value)).filter(Boolean);actions.append(...available.map(item=>{const b=choiceButton(item.label,$('action').value===item.value,()=>{$('action').value=item.value;syncBriefFlow();briefChanged();renderStartChoices();});b.dataset.action=item.value;return b;}));if(!$('action').value)actions.firstElementChild.tabIndex=0;
  const kind=$('work-kind'),old=$('communication').value;kind.replaceChildren(...(route.kinds||[old]).map(value=>{const o=el('option',D.options.find(o=>o.questionId==='S1_Q01'&&o.value===value)?.label||value);o.value=value;return o;}));kind.value=old;$('work-kind-field').hidden=!route.kinds;
  if(focusKey)(focusKey==='purpose'?purpose:actions).querySelector(`[data-${focusKey}="${focusValue}"]`)?.focus();
}
const usageBox=el('div');usageBox.append(document.querySelector('label[for="journey-mode"]'),$('journey-mode'));$('context-form').append(usageBox);
const kindBox=el('div');kindBox.id='work-kind-field';const kindLabel=el('label','Çalışmanın türünü netleştirelim');kindLabel.htmlFor='work-kind';const kindSelect=el('select');kindSelect.id='work-kind';kindBox.append(kindLabel,kindSelect);$('context-form').querySelector('.context-heading').after(kindBox);
$('work-kind').addEventListener('change',()=>{$('communication').value=$('work-kind').value;syncBriefFlow();briefChanged();renderStartChoices();});
renderStartChoices();
function sourceContext(){const creative=state.cards.find(c=>c.id===state.selected);return {...inputs(),creative_id:creative?.id||'unselected',creative_revision:creative?.revision||1,rule_version:D.version};}
window.YaparoSources.configure({mount:$('plan-controls'),readContext:sourceContext,readChannels:()=>state.plan?.rows.filter(r=>r.amount&&!r.owned).map(r=>r.channel.id)||[],channelName:id=>D.channels.find(c=>c.id===id)?.name||id,onChange:()=>{if(state.plan && mode()!=='organic'){invalidate();$('decision-status').textContent='Veri kaynağının durumu değişti. Güncel kaynaklarla dağılımı yeniden öner.';}}});
